    HistoryItem(
      id: "harezmi",
      name: "El-Harezmi",
      category: "kisi",
      date: "780 - 850",
      location: "Bağdat / Harezm",
      respectMessage: "Cebirin babası ve sıfırın kâşifi Harezmi'ye selam olsun...",
      shortDescription: "Matematik, astronomi ve coğrafya bilgini; cebir ilminin kurucusu.",
      fullDescription: "El-Harezmi, modern bilim dünyasının temelini atan, 'Cebir' (Al-Jabr) kitabıyla bu bilim dalına ismini veren ve 'Algoritma' kavramının babası sayılan bir matematik dehasıdır. Sıfırı (0) matematiksel işlemlerde kullanarak rakamlar dünyasında bir devrim yapmış, ondalık sayı sistemini yaygınlaştırmıştır. Bağdat'taki Beytü'l-Hikme'nin en önemli alimlerinden biridir.\n\nOnun yazdığı 'El-Kitabü'l-Muhtasar fi Hisabi'l-Cebri ve'l-Mukabele' adlı eser, yüzyıllarca hem Doğu hem de Batı dünyasında temel otorite kabul edilmiştir. Sadece sayılarla değil, coğrafya ile de ilgilenmiş; yeryüzünün haritasını çizmek için devrim niteliğinde çalışmalar yapmıştır.\n\nBugün kullandığımız bilgisayarlardan uzay teknolojilerine kadar her şeyin temelinde Harezmi'nin cebir kuralları ve algoritmaları yatar. O, aklın ve matematiğin kainatın anahtarı olduğunu tüm dünyaya kanıtlamıştır.",
      imageUrl: null,
      quote: "Matematik, kainatın dilidir.",
      famousQuotes: ["Sıfır, her şeyin yoklukla varlık arasındaki köprüsüdür.", "Cebir, hayatın denklemini çözmektir."],
      legacyWorks: ["Cebir ve Mukabele", "Zic-ul Harezmi"],
      tombLocation: "Bağdat (Manevi Miras)",
      isFeatured: true,
    ),
    HistoryItem(
