      quote: "Devlet, küfürle devam eder ama zulümle devam etmez.",
      famousQuotes: ["Adalet, hükümdarın en sağlam kalesidir.", "İlim, devletin nurudur."],
      legacyWorks: ["Siyasetname", "Nizamiye Medreseleri"],
      tombLocation: "İsfahan, İran",
