    HistoryItem(
      id: "ertugrul_gazi",
      name: "Ertuğrul Gazi",
      category: "kisi",
      date: "1188 - 1281",
      location: "Söğüt, Türkiye",
      respectMessage: "Cihan devletinin müjdecisi, Kayı boyunun yiğit beyine selam...",
      shortDescription: "Osmanlı Devleti'nin kurucusu Osman Gazi'nin babası ve Kayı boyu lideri.",
      fullDescription: "Ertuğrul Gazi, Söğüt ve Domaniç bölgesine yerleşerek altı asır sürecek o büyük çınarın tohumlarını atan kutlu bir bey önderidir. Selçuklu Devleti'nin uç beyi olarak adaletiyle, cengiyle ve imanıyla tanınmıştır. Kayı boyunu büyük bir vakarla yönetmiş, çevredeki tekfurlara ve Moğollara karşı izzetle direnmiştir.\n\nSüleyman Şah'ın oğlu olan Ertuğrul Gazi, oğlu Osman Gazi'ye 'Bizim yolumuz gaza yoludur' vasiyetini bırakarak devletin istikametini belirlemiştir. Söğüt'teki mütevazı obası, bugün cihanşümul bir medeniyetin başlangıç noktası olarak her yıl binlerce kişi tarafından ziyaret edilmektedir.",
      imageUrl: null,
      quote: "Biz ölürsek devlet yaşasın.",
