    HistoryItem(
      id: "mohac_meydan_muharebesi",
      name: "Mohaç Meydan Muharebesi",
      category: "medeniyet",
      date: "1526",
      location: "Mohaç, Macaristan",
      respectMessage: "Dünya tarihinin en kısa ve en etkili meydan zaferine ve o yiğitlere...",
      shortDescription: "Kanuni Sultan Süleyman komutasında kazanılan, Avrupa tarihini değiştiren zafer.",
      fullDescription: "Mohaç Meydan Muharebesi, sadece 2 saat sürmesine rağmen dünya savaş tarihinin en büyük stratejik zaferlerinden biridir. Kanuni Sultan Süleyman kumandandaki Osmanlı ordusu, kendisinden çok daha kalabalık olan Haçlı-Macar ittifakını 'Kıskaç Taktiği' ve ateşli silahların üstünlüğüyle bozguna uğratmıştır. Bu zaferle Macaristan Krallığı sona ermiş ve Orta Avrupa'nın kapıları tamamen İslam sancağına açılmıştır.\n\nSavaş sonrası Kanuni'nin ölen askerler için yas tutması ve kibri ayaklar altına alan vakur duruşu, İslam harp ahlakının zirvesidir. Mohaç, Osmanlı'nın cihan hakimiyetini bir asır boyunca tescilleyen kutlu bir zaferdir.",
      imageUrl: null,
      quote: "Zafer, ancak Allah’ın yardımıyladır.",
      famousQuotes: ["Mohaç, Türk'ün bükülmez bileğidir.", "İki saatte yazılan cihan tarihi."],
      legacyWorks: ["Osmanlı'nın Orta Avrupa Hakimiyeti", "Askeri Strateji Tarihi"],
      tombLocation: "Mohaç (Gıyâbi Şehitlik)",
      isFeatured: true,
    ),
    HistoryItem(
      id: "aliya_izzetbegovic",
      name: "Aliya İzzetbegoviç",
      category: "kisi",
      date: "1925-2003",
      location: "Saraybosna, Bosna-Hersek",
      respectMessage: "Bilge Kral'ın vakur duruşuna ve İslam dünyasına bıraktığı derin mirasa...",
      shortDescription: "Bosna-Hersek'in ilk cumhurbaşkanı, büyük bir mütefekkir ve 'Bilge Kral'.",
      fullDescription: "Aliya İzzetbegoviç, 20. yüzyılın en önemli Müslüman liderlerinden ve düşünürlerinden biridir. Bosna-Hersek’in bağımsızlık mücadelesinde hem askeri hem de siyasi liderlik yaparak halkının özgürlüğü için savaşmıştır. Sadece bir devlet adamı değil, aynı zamanda 'Doğu ve Batı Arasında İslam' ve 'İslam Deklarasyonu' gibi eserleriyle modern dünyada İslam'ın konumunu sorgulayan bir filozoftur.\n\nSavaşın en zorlu günlerinde dahi adaletten ve insan haklarından ödün vermeyen Aliya, 'Savaş ölünce değil, düşmanına benzediğinde kaybedilir' sözüyle evrensel bir ahlak dersi vermiştir. Hapishane yıllarında dahi umudunu yitirmemiş, kalemi ve iradesiyle davasını savunmaya devam etmiştir.\n\nOnun vefatı tüm İslam dünyasında büyük bir hüzne neden olmuştur. Bugün Saraybosna’daki şehitlikte yatan Bilge Kral, sadece Bosnalıların değil, tüm mazlum milletlerin ve hürriyet aşığı kalplerin ortak kahramanı olarak anılmaktadır.",
      imageUrl: null,
      quote: "Hayat kısa, ama diller uzundur; yaptığın iyilik baki kalır.",
      famousQuotes: ["Düşmanına benzediğinde savaşı kaybedersin.", "Her şey bittiğinde hatırlayacağımız, düşmanlarımızın sözleri değil, dostlarımızın sessizliği olacaktır."],
      legacyWorks: ["Doğu ve Batı Arasında İslam", "İslam Deklarasyonu", "Bosna Bağımsızlığı"],
      tombLocation: "Kovaçi Şehitliği, Saraybosna",
      isFeatured: true,
    ),
    HistoryItem(
      id: "necip_fazil_kisakurek",
      name: "Necip Fazıl Kısakürek",
      category: "kisi",
      date: "1904-1983",
      location: "İstanbul, Türkiye",
      respectMessage: "Üstad'ın kaleminin asaletine ve fikir dünyamızdaki devrimci duruşuna...",
      shortDescription: "Türk edebiyatının 'Üstad'ı, şair, yazar ve aksiyon adamı.",
      fullDescription: "Necip Fazıl Kısakürek, Modern Türk edebiyatının ve düşünce tarihinin en sarsıcı figürlerinden biridir. 'Çile' adlı şiir kitabıyla edebiyat dünyasında zirvelere tırmanan Necip Fazıl, aynı zamanda çıkardığı 'Büyük Doğu' dergisiyle bir neslin uyanışına öncülük etmiştir. Şiiri bir 'fildişi kule' sanatı olmaktan çıkarıp, cemiyete yön veren bir 'aksiyon' aracına dönüştürmüştür.\n\nOnun hayatı, 'Mutlak Hakikat'i arayışın hikayesidir. 'Kaldırımlar' şairi olarak başladığı yolculuğu, tasavvufi bir derinlik ve milli bir şuurla taçlandırmıştır. Yazdığı piyesler, felsefi incelemeler ve eşsiz üslubuyla Türkçenin gücünü tüm dünyaya göstermiştir.\n\nÜstad, yaşadığı dönemde birçok zorlukla karşılaşmış, defalarca hapis yatmış ancak inandığı değerlerden asla geri adım atmamıştır. 'Ciğerinden kalemine kan çekerek' yazdığı her satır, bugün hâlâ genç zihinlerde fırtınalar estirmekte ve medeniyet davamızın meşalesi olmaya devam etmektedir.",
      imageUrl: null,
      quote: "Hasis sarraf, kendine bir başka kese diktir; Mezarda geçer akça neyse onu biriktir!",
      famousQuotes: ["Canı canan dileyen, cananı bulmaz mı?", "Tohum saç, bitmezse toprak utansın!"],
      legacyWorks: ["Çile", "Bir Adam Yaratmak", "Büyük Doğu İdeolocya Örgüsü"],
      tombLocation: "Eyüp Sultan, İstanbul",
      isFeatured: true,
    ),
    HistoryItem(
      id: "mehmet_akif_ersoy",
      name: "Mehmet Akif Ersoy",
      category: "kisi",
      date: "1873-1936",
      location: "İstanbul, Türkiye",
      respectMessage: "İstiklal Şairi'nin tevazusuna ve bağımsızlık aşkıyla çarpan kalbine...",
      shortDescription: "İstiklal Marşı'mızın şairi, Kur'an şairi ve vatanperver müteffekir.",
      fullDescription: "Mehmet Akif Ersoy, sadece bir şair değil, bir karakter ve iman abidesidir. Milli Mücadele’nin manevi mimarlarından biri olarak Anadolu’yu karış karış gezmiş ve halkı hürriyet için kıyama davet etmiştir. 'Safahat' adlı dev eseri, toplumsal dertlerin, dini heyecanın ve vatan aşkının en samimi çığlığıdır.\n\nO, paraya ve pula zerre tamah etmemiş, kazandığı ödülü bile ihtiyaç sahiplerine bağışlamış bir 'derviş' ruhludur. Şiirlerinde her zaman adaleti, çalışkanlığı ve İslam kardeşliğini savunmuştur. 'Allah bu millete bir daha İstiklal Marşı yazdırmasın' duasıyla, milletinin bağımsızlığının ebedi kalmasını dilemiştir.\n\nAkif’in hayatı, sürgünlerde ve zorluklarda geçse de vakur duruşundan hiçbir zaman ödün vermemiştir. Bugün İstiklal Marşı’mızın her mısrasında onun ruhu, asırlık çınarlar gibi gölgesini üzerimizde hissettirmekte ve bize yol göstermeye devam etmektedir.",
      imageUrl: null,
      quote: "Sahipsiz olan memleketin batması haktır; Sen sahip olursan bu vatan batmayacaktır.",
      famousQuotes: ["Zulmü alkışlayamam, zalimi asla sevemem.", "Haya sıyrılmış inmiş, öyle yüzler var ki ibretlik."],
      legacyWorks: ["Safahat", "İstiklal Marşı", "Sırat-ı Müstakim Dergisi"],
      tombLocation: "Edirnekapı Şehitliği, İstanbul",
