    HistoryItem(
      id: "el_biruni",
      name: "El-Bironi (Biruni)",
      category: "kisi",
      date: "973-1048",
      location: "Harezm - Gazne",
      respectMessage: "Gökleri ve yerleri ölçen, asrın en büyük dehâsına...",
      shortDescription: "Dünyanın döndüğünü asırlar önce ispatlayan astronom, matematikçi ve coğrafyacı.",
      fullDescription: "El-Biruni, bilim tarihinin en büyük dâhilerinden biri olarak kabul edilir. George Sarton'un ifadesiyle 'bilimin en parlak asrının ismi' olan 11. yüzyıla damgasını vurmuştur. Henüz on sekiz yaşındayken güneşin yüksekliğini ölçen aletler yapmış, yirmi yaşlarındayken boylamları hesaplamak için trigonometriyi geliştirmiştir. O, Batı dünyasından centuries önce dünyanın döndüğünü ve güneş sisteminin yapısını doğru bir şekilde tarif etmiştir.\n\nBiruni'nin en büyük özelliklerinden biri, bilimi sadece teorik değil, pratik ve gözleme dayalı bir şekilde ele almasıdır. Bugün dahi doğruluğu kabul edilen dünyanın çapı ve çevresi hesaplamalarını, Hindistan seferi sırasında bir dağın yamacından yaptığı tek bir ölçümle gerçekleştirmiştir. Karşılaştırmalı dinler tarihinin kurucusu sayılan Biruni, dillerden dinlere, madenlerden bitkilere kadar her konuda binden fazla eser kaleme almıştır.\n\nGazneli Mahmud'un 'Sarayımın en değerli hazinesi' dediği Biruni, gerçeği aramaktan asla vazgeçmemiştir. O, sadece bir Müslüman bilim insanı değil, evrensel düşüncenin en saf temsilcilerinden biridir. Bilimin aydınlığıyla karanlık çağları aydınlatan ruhu, bugün de modern bilimin ve rasyonele dayalı düşüncenin en büyük ilham kaynakları arasındadır.",
      imageUrl: null,
      quote: "Gerçek, bilimin tek gayesidir.",
      famousQuotes: ["Doğruyu aramak bir erdemdir, bulmak ise bir ömre bedeldir.", "Akıl, Allah'ın insana verdiği en büyük nimettir."],
      legacyWorks: ["El-Âsâr'il-Bâkiye", "Tahkîku mâ li'l-Hind"],
